def bands_of(px, y0,y1, x0,x1, thr):
    out=[]; cur=None
    for y in range(y0,y1):
        has = any(sum(px[x,y])<thr for x in range(x0,x1))
        if has and cur is None: cur=y
        elif not has and cur is not None: out.append((cur,y-1)); cur=None
    if cur is not None: out.append((cur,y1-1))
    return out

def ink_runs(px, y0,y1, x0,x1, thr):
    runs=[]; cur=None
    for x in range(x0,x1):
        has = any(sum(px[x,y])<thr for y in range(y0,y1))
        if has and cur is None: cur=x
        elif not has and cur is not None: runs.append((cur,x-1)); cur=None
    if cur is not None: runs.append((cur,x1-1))
    return runs

def darkest(px,y0,y1,x0,x1):
    best=(9999,None)
    for y in range(y0,y1):
        for x in range(x0,x1):
            s=sum(px[x,y])
            if s<best[0]: best=(s,(x,y),px[x,y])
    return best

